<script setup>
import {ref,computed,watch,onUnmounted,onActivated,onDeactivated} from 'vue';
import AuditEvidence from '../components/AuditEvidence.vue';
import AuditInspector from '../components/AuditInspector.vue';
import AuditOverview from '../components/AuditOverview.vue';
import AuditorCatalogs from './AuditorCatalogs.vue';
import DateInput from '../components/DateInput.vue';
import BaseModal from '../components/BaseModal.vue';
import {state,company,api,scope,useResource,allowedApi,can,notify,ask,captureContext,contextMatches} from '../lib/workspace';
import {uid,money,date,dateTime} from '../lib/format';
const props=defineProps({initialSection:{default:'overview'}});
const section=ref(props.initialSection),job=ref(null),busy=ref(false),error=ref(''),files=ref([]),start=ref(''),end=ref(''),name=ref(''),catalogId=ref(''),key=ref(uid()),finding=ref(null),attachment=ref(null),reprocessing=ref(null);
const sources=ref(null),selectedIds=ref([]),sourceSearch=ref(''),search=ref(''),findStatus=ref(''),severity=ref(''),direction=ref(''),documentStatus=ref(''),page=ref(1),historySearch=ref(''),showDeleted=ref(false);
const inspectedRef=ref(null),reportPreview=ref(false),sortKey=ref('issued_at'),sortDesc=ref(false),category=ref('');
const inspected=computed(()=>job.value?.result?.documents.find(d=>d.document_ref===inspectedRef.value));
const counterpart=d=>{const n=d.normalized||{},side=d.direction==='entrada'?'issuer':'recipient';return n[side]?.name||n[side+'_name']||n.partner_name||d[side+'_tax_id']||'—'};
const nf=ref=>job.value?.result?.documents.find(d=>d.document_ref===ref)?.number||'Lote';
function sortBy(key){if(sortKey.value===key)sortDesc.value=!sortDesc.value;else{sortKey.value=key;sortDesc.value=false}}
function inspect(d){inspectedRef.value=d.document_ref}
let timer,active=true;
const {data:history,reload,error:historyError}=useResource(()=>allowedApi('auditor.analyses',scope(`/auditor/jobs?year_value=${state.period.slice(0,4)}`)));
const {data:catalogs,reload:reloadCatalogs}=useResource(()=>allowedApi('auditor.analyses',scope('/auditor/available-catalogs')));
const status=s=>({queued:'Na fila',running:'Em processamento',completed:'Concluída',failed:'Falhou',cancelled:'Cancelada',authorized:'Autorizado no XML',parsed:'Lido',bookkeeping_only:'Somente escrituração',outside_period:'Fora do período',rejected:'Recusado',duplicate:'Duplicado',auxiliary:'PDF auxiliar',event:'Evento',open:'Aberto',reviewing:'Em revisão',resolved:'Tratado',dismissed:'Justificado',critical:'Crítica',high:'Alta',medium:'Média',low:'Baixa',info:'Informativa',reconciled:'Correspondência exata',reconciled_estimate:'Estimativa conciliada',missing_input:'Entrada ausente',negative_margin:'Margem negativa',zero_margin:'Margem zero',in_stock:'Sem saída',review_identity:'Revisar identidade',insufficient_quantity_data:'Quantidades incompletas',insufficient_input_quantity:'Entradas insuficientes'}[s]||s);
const stage=s=>({queued:'Aguardando processamento',recovery:'Retomando trabalho interrompido',reading:'Lendo arquivos',cross_checks:'Conferindo e conciliando',reports:'Gerando PDF e Excel',completed:'Processamento concluído',failed:'Processamento com falha',cancelled:'Processamento cancelado'}[s]||s);
const decimal=v=>v===null||v===undefined?'—':Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:6});
const labels={overview:'Visão geral',analysis:'Análise crítica',internal:'Auditoria da escrituração',standalone:'Auditoria avulsa',history:'Histórico',findings:'Achados',documents:'Documentos',reconciliation:'Conciliação e margens',catalogs:'Catálogos',reports:'Relatórios',logs:'Logs'};
const sourceRows=computed(()=>sources.value?.filter(r=>JSON.stringify(r).toLocaleLowerCase().includes(sourceSearch.value.toLocaleLowerCase()))||[]);
const jobs=computed(()=>history.value.filter(j=>(showDeleted.value||!j.deleted_at)&&JSON.stringify(j).toLocaleLowerCase().includes(historySearch.value.toLocaleLowerCase())));
const documents=computed(()=>(job.value?.result?.documents||[]).filter(d=>(!direction.value||d.direction===direction.value)&&(!documentStatus.value||d.status===documentStatus.value)&&JSON.stringify(d).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())));
const findings=computed(()=>(job.value?.findings||[]).filter(f=>(!findStatus.value||f.status===findStatus.value)&&(!severity.value||f.severity===severity.value)&&(!category.value||f.category===category.value)&&JSON.stringify(f).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())));
const sortedDocuments=computed(()=>[...documents.value].sort((a,b)=>(sortKey.value==='total_value'?Number(a.total_value)-Number(b.total_value):String(sortKey.value==='participant'?counterpart(a):a[sortKey.value]||'').localeCompare(String(sortKey.value==='participant'?counterpart(b):b[sortKey.value]||''),'pt-BR',{numeric:true}))*(sortDesc.value?-1:1)));
const visibleDocuments=computed(()=>sortedDocuments.value.slice((page.value-1)*25,page.value*25));
const visibleFindings=computed(()=>findings.value.slice((page.value-1)*25,page.value*25));
watch(()=>[state.companyId,state.period.slice(0,4)],()=>{start.value=state.period.slice(0,4)+'-01-01';end.value=state.period.slice(0,4)+'-12-31';job.value=null;inspectedRef.value=null;reportPreview.value=false;files.value=[];sources.value=null;selectedIds.value=[];key.value=uid();catalogId.value='';error.value='';clearTimeout(timer)},{immediate:true});
watch([start,end],()=>{sources.value=null;selectedIds.value=[];key.value=uid()});
watch([search,findStatus,severity,category,direction,documentStatus],()=>page.value=1);
onActivated(()=>{active=true;if(job.value)poll()});onDeactivated(()=>{active=false;clearTimeout(timer)});onUnmounted(()=>{clearTimeout(timer);if(finding.value||attachment.value||reprocessing.value)state.editor=null});
const encode=f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});
async function run(fn){if(busy.value||state.contextBusy)return;const ctx=captureContext(),guard={token:Symbol('operation'),name:'Auditor em processamento'};if(!state.editor)state.editor=guard;busy.value=true;error.value='';try{await fn(ctx)}catch(e){if(contextMatches(ctx))error.value=e.message}finally{busy.value=false;if(state.editor?.token===guard.token)state.editor=null}}
async function load(id){const ctx=captureContext();const r=await api(scope(`/auditor/jobs/${id}`,ctx.companyId));if(contextMatches(ctx)){if(job.value?.id!==r.id){inspectedRef.value=null;reportPreview.value=false}job.value=r;if(section.value==='history')section.value='overview';poll()}}
function poll(){clearTimeout(timer);if(active&&['queued','running'].includes(job.value?.status))timer=setTimeout(async()=>{try{const ctx=captureContext(),id=job.value.id;const r=await api(scope(`/auditor/jobs/${id}/progress`,ctx.companyId));if(!contextMatches(ctx)||job.value?.id!==id)return;Object.assign(job.value,r);if(['queued','running'].includes(r.status))poll();else{await load(id);await reload()}}catch(e){error.value=e.message}},1000)}
async function previewSources(){await run(async()=>{sources.value=await api(scope(`/auditor/sources?start=${start.value}&end=${end.value}`));selectedIds.value=sources.value.map(r=>r.id)})}
async function create(){await run(async ctx=>{const mode=section.value==='standalone'?'standalone':'internal';const params={name:name.value,mode,start:start.value,end:end.value,catalog_id:catalogId.value||null,idempotency_key:key.value};if(mode==='internal'&&sources.value){if(!selectedIds.value.length)throw Error('Selecione pelo menos um documento.');params.document_ids=[...selectedIds.value]}let attachments=[];if(mode==='standalone'){if(!files.value.length)throw Error('Selecione arquivos para auditar.');if(files.value.reduce((s,f)=>s+f.size,0)>20*1024*1024)throw Error('Limite de 20 MiB por lote.');for(const f of files.value)attachments.push({filename:f.name,content_base64:await encode(f)})}const r=await api(scope('/auditor/jobs',ctx.companyId),{method:'POST',context:ctx,body:{...params,files:attachments}});key.value=uid();await reload();await load(r.id);section.value='overview';notify('Auditoria enfileirada. A escrituração será preservada.')})}
async function action(action){const ctx=captureContext(),target={id:job.value.id,version:job.value.version};const reason=await ask({title:action==='delete'?'Excluir auditoria do uso corrente?':'Registrar operação',message:'O histórico e os arquivos serão preservados.',inputLabel:'Justificativa',required:true});if(!reason)return;await run(async()=>{job.value=await api(scope(`/auditor/jobs/${target.id}/${action}`,ctx.companyId),{method:'POST',context:ctx,body:{reason,version:target.version}});poll();await reload()})}
async function generateAux(d){await run(async()=>{await api(scope(`/auditor/jobs/${job.value.id}/auxiliary`),{method:'POST',body:{document_ref:d.document_ref}});await load(job.value.id);notify('Documento auxiliar gerado e preservado.')})}
async function reprocess(){await run(async()=>{await reloadCatalogs();reprocessing.value={id:job.value.id,catalog_id:job.value.snapshot.catalog?.id||'',idempotency_key:uid()};state.editor={name:'Reprocessamento do Auditor'}})}
async function confirmReprocess(){await run(async()=>{const f=reprocessing.value;const r=await api(scope(`/auditor/jobs/${f.id}/reprocess`),{method:'POST',body:{idempotency_key:f.idempotency_key,catalog_id:f.catalog_id||null}});await reload();await load(r.id);reprocessing.value=null;state.editor=null;section.value='overview';notify('Nova auditoria criada; resultados anteriores preservados.')})}
function linkPdf(d){attachment.value={document_ref:d.document_ref,file_id:'',reason:''};state.editor={name:'Vincular PDF auxiliar'}}
async function saveAttachment(){await run(async()=>{await api(scope(`/auditor/jobs/${job.value.id}/attachments`),{method:'POST',body:attachment.value});attachment.value=null;state.editor=null;await load(job.value.id);notify('PDF vinculado com registro da revisão; escrituração preservada.')})}
function editFinding(f){finding.value={...f};state.editor={name:'Tratamento de achado'}}
async function discard(){if(await ask({title:'Fechar edição?',message:'Os dados ainda não gravados serão descartados.',confirmLabel:'Descartar'})){finding.value=null;attachment.value=null;reprocessing.value=null;state.editor=null}}
async function saveFinding(){await run(async()=>{await api(scope(`/auditor/findings/${finding.value.id}/treatment`),{method:'PUT',body:finding.value});finding.value=null;state.editor=null;await load(job.value.id);notify('Tratamento registrado. A origem não foi alterada.')})}
function tab(k){section.value=k;page.value=1;search.value='';if(['internal','standalone'].includes(k))reloadCatalogs()}
function fileUrl(id,inline=false){return `/api${scope(`/auditor/jobs/${job.value.id}/files?file_id=${id}${inline?'&inline=1':''}`)}`}
function reportUrl(format,print=false){return `/api${scope(`/auditor/jobs/${job.value.id}/report?format=${format}${print?'&purpose=print':''}`)}`}
</script>
<template><div class="view">
<header class="view-heading"><div><div class="eyebrow">AUDITOR FISCAL</div><h1>{{labels[section]}}</h1><p>{{company?.name}} · Exercício {{state.period.slice(0,4)}} · auditoria sem alteração da escrituração</p></div></header>
<div class="section-tabs auditor-tabs"><button v-for="(label,k) in labels" :key="k" v-show="k==='catalogs'?can('auditor.catalogs'):can('auditor.analyses')" :class="{active:section===k}" @click="tab(k)">{{label}}</button></div>
<p v-if="error||historyError" class="message error" role="alert">{{error||historyError}}</p>
<section v-if="['internal','standalone'].includes(section)" class="panel"><div class="panel-body"><form @submit.prevent="create">
<div class="form-grid"><label>Nome da auditoria<input v-model="name" maxlength="150" placeholder="Identificação do trabalho"/></label><label>De<DateInput v-model="start" required/></label><label>Até<DateInput v-model="end" required/></label><label>Catálogo publicado<select aria-label="Catálogo publicado" v-model="catalogId"><option value="">Sem catálogo — cobertura limitada</option><option v-for="c in catalogs" :key="c.id" :value="c.id">{{c.name}} · {{c.sha256.slice(0,8)}}</option></select></label></div>
<template v-if="section==='standalone'"><label>XML, PDF auxiliar ou ZIP de XML/PDF<input type="file" multiple accept=".xml,.zip,.pdf" @change="files=Array.from($event.target.files);key=uid()"/></label><p v-for="f in files" :key="f.name">{{f.name}} · {{Math.ceil(f.size/1024)}} KiB</p><p>Arquivos avulsos ficam separados da escrituração. Recusas, duplicidades e documentos fora do período permanecem no diagnóstico; os totais identificam a amostra efetivamente analisada.</p></template>
<template v-else><p>Selecione documentos pela data de escrituração. Meses fechados continuam disponíveis para auditoria. A data original de emissão será preservada.</p><button type="button" class="button outline" :disabled="busy" @click="previewSources">Consultar documentos da escrituração</button><template v-if="sources"><label>Pesquisar documentos internos<input v-model="sourceSearch"/></label><div class="actions"><button type="button" class="text-button" @click="selectedIds=sourceRows.map(r=>r.id)">Selecionar resultados</button><button type="button" class="text-button" @click="selectedIds=[]">Limpar seleção</button><span>{{selectedIds.length}} de {{sources.length}} selecionados</span></div><div class="table-scroll source-table"><table><thead><tr><th>Selecionar</th><th>Documento</th><th>Participante</th><th>Emissão / escrituração</th><th>Valor</th><th>Competência</th></tr></thead><tbody><tr v-for="d in sourceRows" :key="d.id"><td><input type="checkbox" v-model="selectedIds" :value="d.id" :aria-label="'Selecionar documento '+d.number"/></td><td>{{d.number}} · {{d.model}}</td><td>{{d.partner_name}}</td><td>{{date(d.issue_date)}} / {{date(d.posting_date)}}</td><td>{{money(d.total_cents)}}</td><td>{{d.closed?'Fechada — consulta permitida':'Aberta'}}</td></tr></tbody></table></div><p v-if="!sources.length">Nenhum documento escriturado no intervalo.</p></template><p v-else>Sem seleção específica, serão auditados todos os documentos do intervalo.</p></template>
<p>Leitura: NF-e/NFC-e, CT-e/CT-e OS, MDF-e e eventos NF-e. Recálculos conforme cobertura; PDF não participa dos cálculos.</p><button class="button primary" v-if="can('auditor.analyses','create')&&(section==='internal'||can('auditor.analyses','import'))" :disabled="busy">Iniciar auditoria</button>
</form></div></section>
<AuditorCatalogs v-else-if="section==='catalogs'" :key="state.companyId"/>
<template v-else>
<section v-if="section==='history'||!job" class="panel"><div class="panel-heading"><h2>Auditorias do exercício</h2><button class="button outline" @click="reload">Atualizar</button></div><div class="panel-body form-grid"><label>Pesquisar histórico<input v-model="historySearch"/></label><label class="check-label"><input type="checkbox" v-model="showDeleted"/>Mostrar excluídas</label></div><div class="table-scroll history-table"><table><thead><tr><th>Auditoria</th><th>Origem / período</th><th>Situação</th><th>Responsável</th><th></th></tr></thead><tbody><tr v-for="h in jobs" :key="h.id"><td>#{{h.id}} · {{h.name}}</td><td>{{h.mode==='internal'?'Escrituração':'Avulsa'}} · {{date(h.start)}} a {{date(h.end)}}</td><td>{{status(h.status)}}{{h.deleted_at?' · excluída':''}}</td><td>{{h.created_by}}</td><td><button class="text-button" @click="run(()=>load(h.id))">Abrir</button></td></tr></tbody></table></div><p class="panel-body" v-if="!jobs.length">Nenhuma auditoria. Utilize Auditoria da escrituração ou Auditoria avulsa para iniciar.</p></section>
<section v-if="job&&section!=='history'" class="panel audit-workspace"><div class="panel-heading"><div><h2>Auditoria #{{job.id}} · {{status(job.status)}}</h2><small>{{job.name}}</small></div><div class="actions"><button v-if="['queued','running'].includes(job.status)&&can('auditor.analyses','edit')" class="button outline" @click="action('cancel')" :disabled="busy">Cancelar</button><template v-if="!['queued','running'].includes(job.status)"><button v-if="!job.deleted_at&&can('auditor.analyses','create')&&(job.mode==='internal'||can('auditor.analyses','import'))" class="button outline" @click="reprocess" :disabled="busy">Reprocessar em novo histórico</button><button v-if="!job.deleted_at&&can('auditor.analyses','delete')" class="button" @click="action('delete')">Excluir logicamente</button><button v-if="job.deleted_at&&can('auditor.analyses','edit')" class="button" @click="action('restore')">Restaurar</button></template></div></div>
<div class="panel-body"><p>{{job.name}} · {{date(job.start)}} a {{date(job.end)}} · {{job.parent_id?'Reprocessamento da auditoria #'+job.parent_id:''}}</p><div v-if="['queued','running'].includes(job.status)" role="status"><progress :value="job.progress" max="100"></progress><p>{{stage(job.stage)}} · {{job.progress}}% · {{job.processed_files}} / {{job.total_files}} arquivos</p></div>
<p v-if="job.stale_document_ids?.length" class="message warning">A escrituração mudou após esta auditoria: documentos {{job.stale_document_ids.join(', ')}}. Reprocesse para obter um novo retrato.</p><p v-if="job.error" class="message error">{{job.error}}</p><p v-if="job.result?.outcome?.rejected" class="message warning">{{job.result.outcome.rejected}} arquivo(s) recusado(s). Consulte o diagnóstico em Documentos; a recusa não foi incluída nos totais.</p>
<AuditOverview v-if="section==='overview'||section==='analysis'" :job="job" :analytical="section==='analysis'" @section="tab" @finding="f=>{tab('findings');search=f.rule_code}"/>
<template v-if="section==='findings'">
<div class="form-grid four"><label>Pesquisar evidência<input v-model="search"/></label><label>Situação<select aria-label="Situação" v-model="findStatus"><option value="">Todas</option><option v-for="s in ['open','reviewing','resolved','dismissed']" :value="s">{{status(s)}}</option></select></label><label>Severidade<select aria-label="Severidade" v-model="severity"><option value="">Todas</option><option v-for="s in ['critical','high','medium','low','info']" :value="s">{{status(s)}}</option></select></label><label>Camada de análise<select aria-label="Camada de análise" v-model="category"><option value="">Todas</option><option v-for="k in Object.keys(job.analytics?.category_counts||{})" :key="k" :value="k">{{k}}</option></select></label></div>
<p class="hint">{{findings.length}} achados nos filtros · selecione a nota para inspecionar a origem e o item.</p>
<article v-for="f in visibleFindings" :key="f.id" class="audit-finding"><div class="finding-heading"><span :class="['severity-badge',f.severity]">{{status(f.severity)}}</span><strong>{{f.title}}</strong><small>{{f.rule_code}} · {{status(f.status)}}</small></div><p>{{f.description}}</p><div class="actions"><button v-if="job.result?.documents.some(d=>d.document_ref===f.document_ref)" class="text-button" @click="inspect(job.result.documents.find(d=>d.document_ref===f.document_ref))">NF {{nf(f.document_ref)}} · item {{f.item_number||'—'}} · Inspecionar documento</button><span v-else>Achado do lote</span><button v-if="!job.deleted_at&&can('auditor.analyses','edit')" class="button outline" @click="editFinding(f)">Registrar tratamento</button></div><div class="finding-columns"><p><b>Impacto</b><br>{{f.impact||'Não quantificado pelo motor.'}}</p><p><b>Ação recomendada</b><br>{{f.recommended_action||'Revisar evidências e cobertura antes de decidir.'}}</p></div><details><summary>Evidência e rastreabilidade</summary><AuditEvidence :value="f.evidence"/></details><p v-if="f.responsible||f.treatment" class="treatment">{{f.responsible}} · {{f.treatment}}</p></article><p v-if="!findings.length">Nenhum achado para os filtros informados.</p>
</template>
<template v-if="section==='documents'"><p>XML original, valores escriturados e memória recalculada permanecem separados.</p><div class="form-grid"><label>Pesquisar documento, item ou participante<input v-model="search"/></label><label>Operação<select aria-label="Operação" v-model="direction"><option value="">Todas</option><option value="entrada">Entradas</option><option value="saida">Saídas</option></select></label><label>Situação do documento<select aria-label="Situação do documento" v-model="documentStatus"><option value="">Todas</option><option v-for="s in ['authorized','parsed','bookkeeping_only','cancelled','outside_period']" :value="s">{{status(s)}}</option></select></label></div>
<p class="hint">{{documents.length}} documentos · clique em Inspecionar para consultar participantes, itens, tributos, XML e documento auxiliar.</p>
<div class="table-scroll audit-documents"><table><thead><tr><th v-for="[key,label] in [['number','Documento'],['issued_at','Emissão'],['participant','Participante'],['direction','Operação'],['total_value','Valor NF']]" :key="key" :aria-sort="sortKey===key?(sortDesc?'descending':'ascending'):'none'"><button class="sort-button" @click="sortBy(key)">{{label}} {{sortKey===key?(sortDesc?'↓':'↑'):''}}</button></th><th>Base IBS/CBS</th><th>IBS / CBS</th><th>Itens</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="d in visibleDocuments" :key="d.document_ref"><td><strong>{{d.number}}</strong><small>Modelo {{d.model}} · série {{d.series||'—'}}</small></td><td>{{date(d.issued_at)}}<small v-if="d.posting_date">Escrit. {{date(d.posting_date)}}</small></td><td>{{counterpart(d)}}</td><td>{{d.direction==='entrada'?'Entrada':'Saída'}}</td><td class="numeric">{{decimal(d.total_value)}}</td><td class="numeric">{{decimal(d.ibs_cbs_base)}}</td><td class="numeric">{{decimal(d.ibs_value)}} / {{decimal(d.cbs_value)}}</td><td>{{d.items.length}}</td><td>{{status(d.status)}}<small>{{d.bookkeeping_id?'Escrituração #'+d.bookkeeping_id:'Avulsa'}}</small></td><td><button class="button outline" :aria-label="'Inspecionar documento '+d.number" @click="inspect(d)">Inspecionar</button></td></tr><tr v-if="!visibleDocuments.length"><td colspan="10">Nenhum documento para os filtros.</td></tr></tbody></table></div>
<details class="file-diagnostics"><summary>Diagnóstico dos arquivos · {{job.result?.file_outcomes?.length||0}} ocorrências</summary>
<h3>Diagnóstico dos arquivos</h3><div class="table-scroll"><table><thead><tr><th>Arquivo original</th><th>Resultado</th><th>Diagnóstico</th></tr></thead><tbody><tr v-for="(o,n) in job.result?.file_outcomes" :key="n"><td><a v-if="can('auditor.analyses','export')" :href="fileUrl(o.id)">{{o.name}}</a><span v-else>{{o.name}}</span><br><code>{{o.sha256.slice(0,16)}}</code></td><td>{{status(o.status)}}</td><td>{{o.error||'—'}}</td></tr></tbody></table></div></details><details><summary>Eventos preservados</summary><AuditEvidence :value="job.result?.events||[]"/></details><details><summary>Retrato da escrituração</summary><AuditEvidence :value="job.snapshot.bookkeeping"/></details>
</template>
<div v-if="['documents','findings'].includes(section)" class="actions"><button class="button" :disabled="page===1" @click="page--">Anterior</button><span>Página {{page}} · {{section==='documents'?documents.length:findings.length}} resultados</span><button class="button" :disabled="page*25>=(section==='documents'?documents.length:findings.length)" @click="page++">Próxima</button></div>
<template v-if="section==='reconciliation'"><p>Custos e margens são estimativas da amostra. Não geram baixas, lançamentos nem movimentação de estoque.</p><div class="table-scroll"><table><thead><tr><th>Produto / identidade</th><th>Critério</th><th>Qtd. entrada / saída</th><th>Entradas / saídas</th><th>Custo / margem estimados</th><th>Situação</th></tr></thead><tbody><tr v-for="r in job.result?.reconciliation" :key="r.key"><td>{{r.identifier}}<br>{{r.ncm}}</td><td>{{r.identity_type}} · {{r.confidence}}</td><td>{{decimal(r.input_quantity)}} / {{decimal(r.output_quantity)}}</td><td>{{decimal(r.input_value)}} / {{decimal(r.output_value)}}</td><td>{{decimal(r.estimated_cost)}} / {{decimal(r.margin)}}</td><td>{{status(r.status)}}<details><summary>Evidência</summary><AuditEvidence :value="r"/></details></td></tr></tbody></table></div></template>
<template v-if="section==='reports'"><h3>Relatório Analítico e Sintético</h3><p>PDF e Excel são gerados durante o processamento e preservados com hash. Novos tratamentos produzem outra revisão do relatório; o histórico anterior permanece disponível.</p><div class="actions" v-if="job.result&&!['queued','running'].includes(job.status)"><a v-if="can('auditor.analyses','export')" class="button primary" :href="reportUrl('pdf')">Exportar PDF</a><a v-if="can('auditor.analyses','export')" class="button outline" :href="reportUrl('xlsx')">Exportar Excel</a><a v-if="can('auditor.analyses','print')" class="button outline" target="_blank" rel="noopener" :href="reportUrl('pdf',true)">Visualizar / imprimir PDF</a></div><div class="report-sections"><article v-for="[title,detail] in [['Resumo executivo','Indicadores, conclusão e ações prioritárias'],['Formação da base','Componentes, XML × recálculo e diferenças'],['Entradas e saídas','Análises separadas, participantes e totalizações'],['Críticas e classificação','Severidade, evidência, impacto e tratamento'],['Conciliação econômica','Identidade, confiança, custo e margem estimados'],['Memória e fontes','Cálculos por item, catálogo, hashes e histórico']]" :key="title"><strong>{{title}}</strong><small>{{detail}}</small></article></div><p class="hint">Excel com painel executivo, navegação entre planilhas, filtros e códigos preservados como texto. Os totais identificam documentos excluídos e cenários sem recálculo.</p><button v-if="job.result&&can('auditor.analyses','print')&&!['queued','running'].includes(job.status)" class="button outline" @click="reportPreview=!reportPreview">{{reportPreview?'Fechar prévia':'Prévia do relatório nesta tela'}}</button><iframe v-if="reportPreview" class="audit-report-preview" :src="reportUrl('pdf',true)" title="Prévia do Relatório Analítico e Sintético"/><details class="report-history"><summary>Revisões preservadas e integridade dos arquivos</summary><div class="table-scroll"><table><thead><tr><th>Artefato</th><th>Gerado em</th><th>Tamanho</th><th>Integridade</th></tr></thead><tbody><tr v-for="r in job.reports" :key="r.id"><td><a v-if="can('auditor.analyses','export')" :href="`/api${scope(`/auditor/jobs/${job.id}/reports/${r.id}`)}`">{{r.format.toUpperCase()}} · revisão {{r.id}}</a><span v-else>{{r.format.toUpperCase()}}</span></td><td>{{dateTime(r.created_at)}}</td><td>{{Math.ceil(r.size_bytes/1024)}} KiB</td><td><code>{{r.sha256.slice(0,20)}}</code></td></tr></tbody></table></div></details></template>
<template v-if="section==='logs'"><a v-if="can('auditor.analyses','export')" :href="`/api${scope(`/auditor/jobs/${job.id}/logs/export`)}`" class="button outline">Exportar logs</a><p v-for="(l,n) in job.logs" :key="n"><code>{{dateTime(l.created_at)}}</code> · {{l.level}} · {{l.message}}</p></template>
</div></section></template>
<AuditInspector v-if="inspected" :document="inspected" :job="job" :busy="busy" :error="error" @close="inspectedRef=null" @auxiliary="generateAux" @link="linkPdf" @treat="editFinding"/>
<BaseModal v-if="reprocessing" title="Reprocessar auditoria" @close="discard"><form id="reprocess-form" @submit.prevent="confirmReprocess"><p>A auditoria #{{reprocessing.id}} e seus relatórios serão preservados. O novo trabalho usará os dados atuais da escrituração, quando a origem for interna.</p><label>Catálogo do novo processamento<select aria-label="Catálogo do novo processamento" v-model="reprocessing.catalog_id"><option value="">Sem catálogo — cobertura limitada</option><option v-for="c in catalogs" :key="c.id" :value="c.id">{{c.name}} · {{c.sha256.slice(0,8)}}</option></select></label><p>Confira a versão antes de confirmar. A escolha inicial corresponde ao catálogo da auditoria de origem.</p><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="discard">Fechar</button><button class="button primary" type="submit" form="reprocess-form" :disabled="busy">Confirmar reprocessamento</button></template></BaseModal>
<BaseModal v-if="attachment" title="Vincular PDF importado" @close="discard"><form id="attachment-form" @submit.prevent="saveAttachment"><p>Confirme o conteúdo do PDF antes de associá-lo. A vinculação não comprova autenticidade nem altera os cálculos.</p><label>PDF do lote<select aria-label="PDF do lote" v-model="attachment.file_id" required><option value="">Selecione</option><option v-for="f in job.snapshot.files.filter(f=>f.name.toLowerCase().endsWith('.pdf'))" :value="f.id">{{f.name}}</option></select></label><a v-if="attachment.file_id&&can('auditor.analyses','export')" :href="fileUrl(attachment.file_id,true)" target="_blank" rel="noopener">Abrir PDF para conferir</a><label>Justificativa da associação<textarea v-model="attachment.reason" required/></label><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="discard">Fechar</button><button class="button primary" form="attachment-form" type="submit" :disabled="busy">Vincular PDF</button></template></BaseModal>
<BaseModal v-if="finding" title="Tratamento do achado" @close="discard"><form id="finding-form" @submit.prevent="saveFinding"><p>O registro de origem permanecerá inalterado.</p><label>Situação<select aria-label="Situação" v-model="finding.status"><option v-for="s in ['open','reviewing','resolved','dismissed']" :value="s">{{status(s)}}</option></select></label><label>Responsável<input v-model="finding.responsible" required autofocus/></label><label>Tratamento e evidência<textarea v-model="finding.treatment" required rows="5"/></label><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="discard">Fechar</button><button class="button primary" type="submit" form="finding-form" :disabled="busy">Salvar</button></template></BaseModal>
</div></template>
<style scoped>.auditor-tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px}.auditor-tabs button{padding:8px;border:1px solid #ccd5d1;border-radius:6px;background:#f6f8f7;color:#243b34}.auditor-tabs button.active{background:#225f57;color:white}.audit-finding{padding:14px 0;border-bottom:1px solid #ddd}.panel-body{padding:18px}.panel{margin-bottom:16px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}.history-table,.source-table{max-height:380px;overflow:auto}td{vertical-align:top}progress{width:100%;accent-color:#225f57}.wrap,code{overflow-wrap:anywhere}summary{cursor:pointer}details{margin:10px 0}.hint{font-size:12px;color:#647d8b;margin:12px 0}.panel-heading small{color:#69808d;font-size:12px}.audit-documents{margin:12px 0}.audit-documents small{display:block;color:#708593;font-size:10px;margin-top:4px}.audit-documents td{padding:13px 10px}.numeric{font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}.sort-button{background:none;border:0;color:inherit;font:inherit;padding:0;cursor:pointer}.finding-heading{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.finding-heading small{margin-left:auto;color:#728894}.severity-badge{padding:4px 9px;border-radius:12px;background:#eef3f6;font-size:11px}.severity-badge.high,.severity-badge.critical{background:#fce7e2;color:#a83f31}.severity-badge.medium{background:#fff1d0;color:#866319}.finding-columns{display:grid;grid-template-columns:1fr 1fr;gap:18px;background:#f6f8fa;padding:12px;border-radius:6px;font-size:12px}.treatment{background:#eaf3ef;padding:10px;border-left:3px solid #488676;font-size:12px}.file-diagnostics,.report-history{border-top:1px solid #dee6ea;margin-top:18px;padding-top:12px}.report-sections{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.report-sections article{padding:16px;background:#f1f6f7;border:1px solid #d8e5e7;border-radius:7px;display:flex;flex-direction:column;gap:8px}.report-sections small{font-size:12px;color:#627c8a}.audit-report-preview{width:100%;height:680px;border:1px solid #ccd9df;margin-top:18px}@media(max-width:800px){.report-sections{grid-template-columns:repeat(2,minmax(0,1fr))}.form-grid.four{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.report-sections,.finding-columns,.form-grid.four{grid-template-columns:1fr}.panel-body{padding:12px}.finding-heading small{margin-left:0}.audit-report-preview{height:480px}}</style>
